cambiar('estilo',
        '                                                   #e3e7eb 4px, #e3e7eb 8px);\n             cursor: zoom-in; padding: 0; }\n\n/* La cartera del implantado: cada mes con su fase, en renglones. */\n.mes-fase { display: flex; gap: 6px; align-items: baseline; margin: 0 0 5px;\n            font-size: 12px; white-space: nowrap; }\n',
        '                                                   #e3e7eb 4px, #e3e7eb 8px);\n             cursor: zoom-in; padding: 0; }\n\n/* El historial de lo facturado (seccion 69). La miniatura de una foto que\n   ya se fue al archivo se queda gris y no se pide. */\n.miniatura.archivada { cursor: default; opacity: .9; }\n.filtros { display: flex; gap: 10px; align-items: flex-end; flex-wrap: wrap;\n           padding: 12px 14px; background: #fff; border: 1px solid var(--linea);\n           border-radius: 8px; margin-bottom: 12px; }\n.filtros .campo { margin: 0; }\n.filtros select { width: auto; min-width: 120px; }\n.filtros input { width: 140px; }\n.filtros .empuja { flex: 1 1 auto; }\n.resumen-filtro { font-size: 13px; color: #3b4450; margin: 2px 2px 10px; }\n.resumen-filtro b { color: #1c1f22; }\nb.folio { white-space: nowrap; }\n.volver { display: inline-block; margin-bottom: 8px; color: var(--centauro);\n          font-weight: 600; font-size: 13px; text-decoration: none; }\n/* El visor: la foto encima de la pantalla, sin abrir otra ventana. */\n.visor-fondo { position: fixed; inset: 0; z-index: 50; display: flex;\n               align-items: center; justify-content: center; padding: 16px;\n               background: rgba(28, 31, 34, .45); }\n.visor { width: min(440px, 100%); max-height: calc(100vh - 32px); overflow: auto;\n         background: #fff; border-radius: 10px; padding: 16px;\n         box-shadow: 0 10px 30px rgba(20, 30, 40, .18); }\n.visor img { display: block; max-width: 100%; margin: 10px auto 12px;\n             border-radius: 6px; border: 1px solid var(--linea); }\n\n/* La cartera del implantado: cada mes con su fase, en renglones. */\n.mes-fase { display: flex; gap: 6px; align-items: baseline; margin: 0 0 5px;\n            font-size: 12px; white-space: nowrap; }\n')

